#!/usr/bin/env bash
# Regenerates .claude/commands/, .claude/skills/, and CLAUDE.md from
# .agents/commands/ and .agents/skills/ so Claude Code can discover them
# natively as /name entries.
#
# .agents/ stays the single source of truth. Every generated file is a thin
# pointer back to its .agents/ source — do not hand-edit anything under
# .claude/commands/, .claude/skills/, or CLAUDE.md; edit the .agents/ file
# and rerun this script instead.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
AGENTS_DIR="$ROOT/.agents"
CLAUDE_DIR="$ROOT/.claude"

extract_description() {
  # First "description:" line inside the leading YAML frontmatter block only.
  sed -n '/^---$/,/^---$/p' "$1" | sed -n 's/^description: *//p' | head -1
}

rm -rf "$CLAUDE_DIR/commands" "$CLAUDE_DIR/skills"
mkdir -p "$CLAUDE_DIR/commands" "$CLAUDE_DIR/skills"

echo "Generating .claude/commands/ from .agents/commands/ ..."
for cmd_file in "$AGENTS_DIR"/commands/*.md; do
  name="$(basename "$cmd_file" .md)"
  description="$(extract_description "$cmd_file")"
  out="$CLAUDE_DIR/commands/$name.md"
  cat > "$out" <<EOF
---
description: ${description}
---

<!-- GENERATED by .agents/hooks/sync-claude-native.sh — do not edit by hand. -->

Follow the instructions in \`.agents/commands/$name.md\` exactly, step by step.
EOF
  echo "  /$name -> .agents/commands/$name.md"
done

echo "Generating .claude/skills/ from .agents/skills/ ..."
for skill_dir in "$AGENTS_DIR"/skills/*/; do
  name="$(basename "$skill_dir")"
  skill_file="$skill_dir/SKILL.md"
  [ -f "$skill_file" ] || continue
  description="$(extract_description "$skill_file")"

  out_dir="$CLAUDE_DIR/skills/$name"
  mkdir -p "$out_dir"
  cat > "$out_dir/SKILL.md" <<EOF
---
name: ${name}
description: ${description}
user-invocable: false
---

<!-- GENERATED by .agents/hooks/sync-claude-native.sh — do not edit by hand. -->

Follow the instructions in \`.agents/skills/$name/SKILL.md\` exactly.
EOF
  echo "  /$name -> .agents/skills/$name/SKILL.md"
done

echo "Generating CLAUDE.md ..."
cat > "$ROOT/CLAUDE.md" <<EOF
@AGENTS.md

<!-- GENERATED by .agents/hooks/sync-claude-native.sh — do not edit by hand. -->

## Claude Code

Commands and skills are also registered natively, generated from the \`.agents/\` sources:
- \`.claude/commands/\` — one entry per \`.agents/commands/*.md\`, invoke directly with \`/name\`.
- \`.claude/skills/\` — one entry per \`.agents/skills/*/SKILL.md\`, \`user-invocable: false\` so Claude loads them autonomously by description match, never as a typed \`/name\`.

Both are generated by [\`.agents/hooks/sync-claude-native.sh\`](.agents/hooks/sync-claude-native.sh). Never hand-edit files under \`.claude/commands/\`, \`.claude/skills/\`, or this file — edit the \`.agents/\` source and rerun the script.
EOF
echo "  CLAUDE.md"

echo "Done."
